function perfectpixel_delivery_range() {
	$today = new DateTimeImmutable( 'today', wp_timezone() );
	return array(
		$today->modify( '+' . max( 0, (int) '{{delivery_min_days}}' ) . ' days' ),
		$today->modify( '+' . max( 0, (int) '{{delivery_max_days}}' ) . ' days' ),
		array_map( 'intval', array_filter( array_map( 'trim', explode( ',', '{{delivery_closed_days}}' ) ), 'strlen' ) ),
	);
}

function perfectpixel_delivery_date_field() {
	list( $min, $max ) = perfectpixel_delivery_range();
	woocommerce_form_field(
		'perfectpixel_delivery_date',
		array(
			'type'              => 'date',
			'label'             => '{{delivery_label}}',
			'required'          => true,
			'class'             => array( 'form-row-wide' ),
			'custom_attributes' => array(
				'min' => $min->format( 'Y-m-d' ),
				'max' => $max->format( 'Y-m-d' ),
			),
		),
		WC()->checkout()->get_value( 'perfectpixel_delivery_date' )
	);
}

function perfectpixel_delivery_date_is_valid( $value ) {
	list( $min, $max, $closed ) = perfectpixel_delivery_range();
	$date = DateTimeImmutable::createFromFormat( '!Y-m-d', (string) $value, wp_timezone() );
	return $date && $date >= $min && $date <= $max && ! in_array( (int) $date->format( 'w' ), $closed, true );
}

function perfectpixel_delivery_date_validate() {
	$value = isset( $_POST['perfectpixel_delivery_date'] ) ? sanitize_text_field( wp_unslash( $_POST['perfectpixel_delivery_date'] ) ) : ''; // phpcs:ignore WordPress.Security.NonceVerification
	if ( ! perfectpixel_delivery_date_is_valid( $value ) ) {
		wc_add_notice( esc_html( '{{delivery_error}}' ), 'error' );
	}
}

function perfectpixel_delivery_date_save( $order, $data ) {
	$value = isset( $_POST['perfectpixel_delivery_date'] ) ? sanitize_text_field( wp_unslash( $_POST['perfectpixel_delivery_date'] ) ) : ''; // phpcs:ignore WordPress.Security.NonceVerification
	if ( perfectpixel_delivery_date_is_valid( $value ) ) {
		$order->update_meta_data( '_perfectpixel_delivery_date', $value );
	}
}

function perfectpixel_delivery_date_show( $order ) {
	if ( ! $order instanceof WC_Order ) {
		return;
	}
	$value = $order->get_meta( '_perfectpixel_delivery_date' );
	if ( $value ) {
		printf( '<p><strong>%s:</strong> %s</p>', esc_html( '{{delivery_label}}' ), esc_html( date_i18n( get_option( 'date_format' ), strtotime( $value ) ) ) );
	}
}
